fun {α : Type u} (u : α → Option α) (hu : ∀ (x y : α), y ∈ u x → y ∈ u y) (s : α → α → Prop) =>
  { up := fun (x : α) => ↑(u x), up_idem := Motion.ofOption._proof_1 u hu, step := s }
def ZeroParadox.Motion.ofPartialFun.{u} : {α : Type u} → (α → Option α) → Motion α :=
